namespace MoongTangE {
namespace {

std::string instance_id()
{
    // Restart identifier only; admission credentials are generated by the matching service.
    std::random_device source;
    constexpr std::string_view HEX = "0123456789abcdef";
    std::string result;
    for (unsigned index = 0; index < 8; ++index) {
        const auto value = static_cast<std::uint32_t>(source());
        for (unsigned digit = 0; digit < 8; ++digit) {
            result += HEX[(value >> (digit * 4)) & 15];
        }
    }
    return result;
}

std::string_view reservation_status(ReservationStatus status)
{
    switch (status) {
    case ReservationStatus::UNKNOWN:
        return "unknown";
    case ReservationStatus::PENDING:
        return "pending";
    case ReservationStatus::RESERVED:
        return "reserved";
    case ReservationStatus::CONSUMED:
        return "consumed";
    case ReservationStatus::FULL:
        return "full";
    case ReservationStatus::EXPIRED:
        return "expired";
    case ReservationStatus::CANCELLED:
        return "cancelled";
    case ReservationStatus::UNAVAILABLE:
        return "unavailable";
    }
    return "unavailable";
}

void json_response(httplib::Response& response, int status, const std::string& body)
{
    response.status = status;
    response.set_header("Cache-Control", "no-store");
    response.set_content(body, "application/json");
}

} // namespace

MatchmakingApi::MatchmakingApi(std::shared_ptr<ServerHost> host, const std::string& address,
                               std::uint16_t port, std::string apiKey, std::uint16_t gamePort,
                               bool requireTicket, unsigned reservationSeconds)
    : m_host(std::move(host)), m_apiKey(std::move(apiKey)), m_instanceId(instance_id()),
      m_gamePort(gamePort), m_requireTicket(requireTicket),
      m_reservationSeconds(reservationSeconds), m_httpServer(std::make_unique<httplib::Server>())
{
    if (!m_host || !m_host->Running() || m_apiKey.size() < 32 || m_apiKey.size() > 128 ||
        !std::all_of(m_apiKey.begin(), m_apiKey.end(), [](char value) {
            return value >= '!' && value <= '~';
        })) {
        throw std::invalid_argument("API requires a running core and a 32..128 character API key");
    }
    m_httpServer->new_task_queue = [] {
        return new httplib::ThreadPool(4, 4, 16);
    };
    m_httpServer->set_read_timeout(1, 0);
    m_httpServer->set_write_timeout(1, 0);
    m_httpServer->set_keep_alive_max_count(1);
    m_httpServer->set_payload_max_length(1024);
    m_httpServer->Get("/v1/status", [this](const auto& request, auto& response) {
        Status(request, response);
    });
    m_httpServer->Get("/v1/reservations", [this](const auto& request, auto& response) {
        Reservation(request, response, ReservationOperation::LOOKUP);
    });
    m_httpServer->Put("/v1/reservations", [this](const auto& request, auto& response) {
        Reservation(request, response, ReservationOperation::RESERVE);
    });
    m_httpServer->Delete("/v1/reservations", [this](const auto& request, auto& response) {
        Reservation(request, response, ReservationOperation::CANCEL);
    });

    const int boundPort = port == 0 ? m_httpServer->bind_to_any_port(address)
                                    : (m_httpServer->bind_to_port(address, port) ? port : -1);
    if (boundPort <= 0) {
        throw std::runtime_error("Cannot bind matchmaking API");
    }
    m_boundPort = static_cast<std::uint16_t>(boundPort);
    m_httpThread = std::thread([this] {
        m_httpServer->listen_after_bind();
    });
    m_httpServer->wait_until_ready();
}

MatchmakingApi::~MatchmakingApi()
{
    m_httpServer->stop();
    if (m_httpThread.joinable()) {
        m_httpThread.join();
    }
}

std::uint16_t MatchmakingApi::Port() const
{
    return m_boundPort;
}

bool MatchmakingApi::Authorize(const httplib::Request& request, httplib::Response& response) const
{
    const auto expected = "Bearer " + m_apiKey;
    const auto supplied = request.get_header_value("Authorization");
    unsigned difference = supplied.size() == expected.size() ? 0U : 1U;
    for (std::size_t index = 0; index < expected.size(); ++index) {
        const auto actual = index < supplied.size() ? supplied[index] : '\0';
        difference |= static_cast<unsigned>(static_cast<unsigned char>(actual) ^
                                            static_cast<unsigned char>(expected[index]));
    }
    if (difference != 0 || request.get_header_value_count("Authorization") != 1) {
        response.set_header("WWW-Authenticate", "Bearer");
        json_response(response, 401, R"({"error":"unauthorized"})");
        return false;
    }
    if (!request.body.empty() || !request.params.empty()) {
        json_response(response, 400, R"({"error":"body_and_query_must_be_empty"})");
        return false;
    }
    return true;
}

void MatchmakingApi::Status(const httplib::Request& request, httplib::Response& response) const
{
    if (!Authorize(request, response)) {
        return;
    }
    const auto state = m_host->Matchmaking();
    const auto age = std::chrono::duration_cast<std::chrono::milliseconds>(
                         std::chrono::steady_clock::now() - state.updatedAt)
                         .count();
    const bool ready = state.running && state.tick != 0 && age < 1000;
    std::size_t players = 0;
    std::size_t reserved = 0;
    std::string rooms = "[";
    for (const auto& room : state.rooms) {
        if (rooms.size() > 1) {
            rooms += ',';
        }
        rooms += "{\"room_id\":\"" + std::to_string(room.roomId) +
                 "\",\"players\":" + std::to_string(room.players) +
                 ",\"reserved\":" + std::to_string(room.reserved) + '}';
        players += room.players;
        reserved += room.reserved;
    }
    rooms += ']';
    json_response(response, ready ? 200 : 503,
                  "{\"instance_id\":\"" + m_instanceId +
                      "\",\"ready\":" + (ready ? "true" : "false") +
                      ",\"protocol_version\":" + std::to_string(wire::PROTOCOL_VERSION) +
                      ",\"game_port\":" + std::to_string(m_gamePort) +
                      ",\"require_ticket\":" + (m_requireTicket ? "true" : "false") +
                      ",\"reservation_seconds\":" + std::to_string(m_reservationSeconds) +
                      ",\"players_per_room\":3,\"capacity\":" + std::to_string(m_host->Capacity()) +
                      ",\"players\":" + std::to_string(players) +
                      ",\"reserved\":" + std::to_string(reserved) +
                      ",\"available\":" + std::to_string(m_host->Capacity() - players - reserved) +
                      ",\"tick\":\"" + std::to_string(state.tick) + "\",\"tick_age_ms\":" +
                      std::to_string(state.tick == 0 ? -1 : age) + ",\"rooms\":" + rooms + '}');
}

void MatchmakingApi::Reservation(const httplib::Request& request, httplib::Response& response,
                                 ReservationOperation operation)
{
    if (!Authorize(request, response)) {
        return;
    }
    if (request.get_header_value_count("X-Server-Instance") != 1 ||
        request.get_header_value("X-Server-Instance") != m_instanceId) {
        json_response(response, 409, R"({"error":"instance_mismatch"})");
        return;
    }
    const auto ticket = request.get_header_value("X-Admission-Ticket");
    if (request.get_header_value_count("X-Admission-Ticket") != 1 ||
        !valid_admission_ticket(ticket)) {
        json_response(response, 400, R"({"error":"invalid_ticket"})");
        return;
    }

    ReservationResult result;
    if (operation == ReservationOperation::RESERVE) {
        result = m_host->Reserve(ticket);
    } else if (operation == ReservationOperation::CANCEL) {
        result = m_host->Reservation(ticket);
        if (result.status != ReservationStatus::UNKNOWN) {
            if (!m_host->CancelReservation(ticket)) {
                result.status = ReservationStatus::UNAVAILABLE;
            } else if (result.status == ReservationStatus::PENDING ||
                       result.status == ReservationStatus::RESERVED) {
                result.status = ReservationStatus::PENDING;
            }
        }
    } else {
        result = m_host->Reservation(ticket);
    }

    int status = 200;
    switch (result.status) {
    case ReservationStatus::PENDING:
        status = 202;
        break;
    case ReservationStatus::UNKNOWN:
        status = 404;
        break;
    case ReservationStatus::FULL:
        status = 409;
        break;
    case ReservationStatus::EXPIRED:
    case ReservationStatus::CANCELLED:
        status = 410;
        break;
    case ReservationStatus::UNAVAILABLE:
        status = 503;
        break;
    default:
        break;
    }
    json_response(response, status,
                  "{\"status\":\"" + std::string(reservation_status(result.status)) +
                      "\",\"room_id\":\"" + std::to_string(result.roomId) +
                      "\",\"expires_in_ms\":" + std::to_string(result.expiresInMs) + '}');
}

} // namespace MoongTangE
